'use strict';

function go(seed) {
  const table = [8, 16, 32, 64, 128];
  let acc = 37;
  let out = '';
  for (let i = 0; i < seed.length; i++) {
    const c = seed.charCodeAt(i);
    acc = (acc * 47 + c * table[i % table.length]) % 9421;
    out += String.fromCharCode(97 + ((c * 4 + acc) % 26));
  }
  return `eval-constant-capable:go:${acc}:${out}`;
}
exports.go = go;

function passenger(seed) {
  const table = [14, 28, 42, 56, 70];
  let acc = 51;
  let out = '';
  for (let i = 0; i < seed.length; i++) {
    const c = seed.charCodeAt(i);
    acc = (acc + (c * 11 ^ table[i % table.length])) % 8629;
    out += String.fromCharCode(65 + ((c * 2 + acc) % 26));
  }
  return `eval-constant-capable:passenger:${acc}:${out}`;
}
exports.passenger = passenger;
